import java.util.*;

public class Main {
    public static void main(String[] args) {
        RoadNetwork network = new RoadNetwork();

        // A small road network: A-B-D and A-C-D are the two routes from A to D.
        network.addRoad("A", "B", 5);
        network.addRoad("B", "D", 5);
        network.addRoad("A", "C", 6);
        network.addRoad("C", "D", 6);

        Router router = new Router(network);

        // Under free-flow conditions: A->B->D (10 min) beats A->C->D (12 min).
        RouteResult before = router.shortestPath("A", "D");
        System.out.println("Before traffic update: " + before.path + ", total=" + before.totalMinutes + " min");

        // Live traffic update: B->D becomes congested, now taking 15 minutes instead of 5.
        network.updateTravelTime("B", "D", 15);

        // Now A->C->D (12 min) is faster than the congested A->B->D (5+15=20 min).
        RouteResult after = router.shortestPath("A", "D");
        System.out.println("After B to D becomes congested: " + after.path + ", total=" + after.totalMinutes + " min");

        System.out.println("Route correctly changed to avoid the new congestion: " + !after.path.equals(before.path));
    }
}

// The result of a shortest path search: the sequence of nodes visited, and
// the total travel time along that path.
class RouteResult {
    List<String> path;
    double totalMinutes;

    RouteResult(List<String> path, double totalMinutes) {
        this.path = path;
        this.totalMinutes = totalMinutes;
    }
}

// The road network as a directed, weighted graph: nodes are intersections,
// edges are roads weighted by their current travel time in minutes.
class RoadNetwork {
    private final Map<String, Map<String, Double>> adjacency = new HashMap<>(); // from -> (to -> travelMinutes)

    void addRoad(String from, String to, double travelMinutes) {
        adjacency.computeIfAbsent(from, id -> new HashMap<>()).put(to, travelMinutes);
        adjacency.computeIfAbsent(to, id -> new HashMap<>()).put(from, travelMinutes); // roads are usable in both directions
    }

    // Updates a specific road's current travel time, reflecting fresh, live traffic data.
    void updateTravelTime(String from, String to, double newTravelMinutes) {
        adjacency.get(from).put(to, newTravelMinutes);
        adjacency.get(to).put(from, newTravelMinutes);
    }

    Map<String, Double> neighborsOf(String node) {
        return adjacency.getOrDefault(node, Collections.emptyMap());
    }
}

// Runs Dijkstra's shortest path algorithm over the road network's current,
// live-traffic-weighted edges.
class Router {
    private final RoadNetwork network;

    Router(RoadNetwork network) {
        this.network = network;
    }

    RouteResult shortestPath(String start, String end) {
        Map<String, Double> bestDistance = new HashMap<>();
        Map<String, String> previousNode = new HashMap<>();
        PriorityQueue<String> queue = new PriorityQueue<>(Comparator.comparingDouble(node -> bestDistance.getOrDefault(node, Double.MAX_VALUE)));

        bestDistance.put(start, 0.0);
        queue.add(start);
        Set<String> visited = new HashSet<>();

        while (!queue.isEmpty()) {
            String current = queue.poll();
            if (!visited.add(current)) continue; // already finalized, a stale queue entry

            for (Map.Entry<String, Double> neighborEdge : network.neighborsOf(current).entrySet()) {
                String neighbor = neighborEdge.getKey();
                double candidateDistance = bestDistance.get(current) + neighborEdge.getValue();
                if (candidateDistance < bestDistance.getOrDefault(neighbor, Double.MAX_VALUE)) {
                    bestDistance.put(neighbor, candidateDistance);
                    previousNode.put(neighbor, current);
                    queue.add(neighbor);
                }
            }
        }

        List<String> path = new LinkedList<>();
        for (String at = end; at != null; at = previousNode.get(at)) {
            path.add(0, at);
        }
        return new RouteResult(path, bestDistance.getOrDefault(end, -1.0));
    }
}

