import heapq


class RouteResult:
    # The result of a shortest path search: the sequence of nodes visited, and
    # the total travel time along that path.
    def __init__(self, path, total_minutes):
        self.path = path
        self.total_minutes = total_minutes


class RoadNetwork:
    # The road network as a directed, weighted graph: nodes are intersections,
    # edges are roads weighted by their current travel time in minutes.
    def __init__(self):
        self.adjacency = {}  # from -> {to: travelMinutes}

    def add_road(self, from_node, to_node, travel_minutes):
        self.adjacency.setdefault(from_node, {})[to_node] = travel_minutes
        self.adjacency.setdefault(to_node, {})[from_node] = travel_minutes  # roads are usable in both directions

    def update_travel_time(self, from_node, to_node, new_travel_minutes):
        self.adjacency[from_node][to_node] = new_travel_minutes
        self.adjacency[to_node][from_node] = new_travel_minutes

    def neighbors_of(self, node):
        return self.adjacency.get(node, {})


class Router:
    # Runs Dijkstra's shortest path algorithm over the road network's current,
    # live-traffic-weighted edges.
    def __init__(self, network):
        self.network = network

    def shortest_path(self, start, end):
        best_distance = {start: 0.0}
        previous_node = {}
        queue = [(0.0, start)]
        visited = set()

        while queue:
            current_distance, current = heapq.heappop(queue)
            if current in visited:
                continue  # already finalized, a stale queue entry
            visited.add(current)

            for neighbor, edge_weight in self.network.neighbors_of(current).items():
                candidate_distance = best_distance[current] + edge_weight
                if candidate_distance < best_distance.get(neighbor, float('inf')):
                    best_distance[neighbor] = candidate_distance
                    previous_node[neighbor] = current
                    heapq.heappush(queue, (candidate_distance, neighbor))

        path = []
        at = end
        while at is not None:
            path.insert(0, at)
            at = previous_node.get(at)

        return RouteResult(path, best_distance.get(end, -1.0))


def main():
    network = RoadNetwork()

    # A small road network: A-B-D and A-C-D are the two routes from A to D.
    network.add_road("A", "B", 5)
    network.add_road("B", "D", 5)
    network.add_road("A", "C", 6)
    network.add_road("C", "D", 6)

    router = Router(network)

    # Under free-flow conditions: A->B->D (10 min) beats A->C->D (12 min).
    before = router.shortest_path("A", "D")
    print(f"Before traffic update: {before.path}, total={before.total_minutes} min")

    # Live traffic update: B->D becomes congested, now taking 15 minutes instead of 5.
    network.update_travel_time("B", "D", 15)

    # Now A->C->D (12 min) is faster than the congested A->B->D (5+15=20 min).
    after = router.shortest_path("A", "D")
    print(f"After B to D becomes congested: {after.path}, total={after.total_minutes} min")

    print("Route correctly changed to avoid the new congestion:", after.path != before.path)


if __name__ == "__main__":
    main()

