#include <iostream>
#include <map>
#include <vector>
#include <queue>
#include <set>
#include <string>
#include <limits>
using namespace std;

// The result of a shortest path search: the sequence of nodes visited, and
// the total travel time along that path.
struct RouteResult {
    vector<string> path;
    double totalMinutes;
};

// The road network as a directed, weighted graph: nodes are intersections,
// edges are roads weighted by their current travel time in minutes.
class RoadNetwork {
public:
    void addRoad(const string& from, const string& to, double travelMinutes) {
        adjacency[from][to] = travelMinutes;
        adjacency[to][from] = travelMinutes; // roads are usable in both directions
    }

    void updateTravelTime(const string& from, const string& to, double newTravelMinutes) {
        adjacency[from][to] = newTravelMinutes;
        adjacency[to][from] = newTravelMinutes;
    }

    const map<string, double>& neighborsOf(const string& node) {
        return adjacency[node];
    }

private:
    map<string, map<string, double>> adjacency; // from -> (to -> travelMinutes)
};

// Runs Dijkstra's shortest path algorithm over the road network's current,
// live-traffic-weighted edges.
class Router {
public:
    Router(RoadNetwork& network) : network(network) {}

    RouteResult shortestPath(const string& start, const string& end) {
        map<string, double> bestDistance;
        map<string, string> previousNode;
        priority_queue<pair<double, string>, vector<pair<double, string>>, greater<>> queue;

        bestDistance[start] = 0.0;
        queue.push({0.0, start});
        set<string> visited;

        while (!queue.empty()) {
            auto [currentDistance, current] = queue.top();
            queue.pop();
            if (visited.count(current)) continue; // already finalized, a stale queue entry
            visited.insert(current);

            for (const auto& [neighbor, edgeWeight] : network.neighborsOf(current)) {
                double candidateDistance = bestDistance[current] + edgeWeight;
                if (!bestDistance.count(neighbor) || candidateDistance < bestDistance[neighbor]) {
                    bestDistance[neighbor] = candidateDistance;
                    previousNode[neighbor] = current;
                    queue.push({candidateDistance, neighbor});
                }
            }
        }

        vector<string> path;
        string at = end;
        while (!at.empty()) {
            path.insert(path.begin(), at);
            auto it = previousNode.find(at);
            at = (it != previousNode.end()) ? it->second : "";
        }

        double total = bestDistance.count(end) ? bestDistance[end] : -1.0;
        return {path, total};
    }

private:
    RoadNetwork& network;
};

int main() {
    RoadNetwork network;

    // A small road network: A-B-D and A-C-D are the two routes from A to D.
    network.addRoad("A", "B", 5);
    network.addRoad("B", "D", 5);
    network.addRoad("A", "C", 6);
    network.addRoad("C", "D", 6);

    Router router(network);

    // Under free-flow conditions: A->B->D (10 min) beats A->C->D (12 min).
    RouteResult before = router.shortestPath("A", "D");
    cout << "Before traffic update: ";
    for (const auto& node : before.path) cout << node << " ";
    cout << ", total=" << before.totalMinutes << " min" << endl;

    // Live traffic update: B->D becomes congested, now taking 15 minutes instead of 5.
    network.updateTravelTime("B", "D", 15);

    // Now A->C->D (12 min) is faster than the congested A->B->D (5+15=20 min).
    RouteResult after = router.shortestPath("A", "D");
    cout << "After B to D becomes congested: ";
    for (const auto& node : after.path) cout << node << " ";
    cout << ", total=" << after.totalMinutes << " min" << endl;

    cout << "Route correctly changed to avoid the new congestion: " << (after.path != before.path ? "true" : "false") << endl;

    return 0;
}

